diff --git a/scripts/v0/optimizer/arc_composition.ts b/scripts/v0/optimizer/arc_composition.ts
index 043d40c7..27f27aa1 100644
--- a/scripts/v0/optimizer/arc_composition.ts
+++ b/scripts/v0/optimizer/arc_composition.ts
@@ -9,7 +9,9 @@ import type {Spec} from '../types.ts';
 export type ArcSectionStyles = NonNullable<ArcMotionOptions['sectionStyles']>;

 export function composeArcSections(spec:Spec, seed:number,
-  reference:ReturnType<typeof compileArcMotion>, styles:ArcSectionStyles, budget:number){
+  reference:ReturnType<typeof compileArcMotion>, styles:ArcSectionStyles, budget:number,
+  search:{futureEstimate?:'learned'|'simulated'}={}){
+  if(search.futureEstimate!==undefined&&!['learned','simulated'].includes(search.futureEstimate))throw new Error('invalid composition future estimate');
   const sections=Object.keys(styles).map(Number).sort((a,b)=>a-b);
   if(!sections.length||!sections.every(i=>Number.isSafeInteger(i)&&i>=0&&i<reference.rows.length))
     throw new Error('composition requires valid support sections');
@@ -24,6 +26,10 @@ export function composeArcSections(spec:Spec, seed:number,
   const fork={...captured.fork,guides:styles[section].guides??true,
     continuation:reference.rows.slice(section).map(r=>({control:r.control,incoming:r.incoming,span:r.span}))};
   const result=compileArcMotion(spec,seed,{...connectedArcOptions(spec,allowance),
+    // Keep learned control proposals, but optionally rank future motion only
+    // through actual continuation simulation. Useful when its geometry differs
+    // from the arc distribution used to train the future-value model.
+    ...(search.futureEstimate==='simulated'?{futureValueModel:undefined}:{}),
     collectTrajectoryLoss:true,sectionStyles:styles,fork});
   const physicalFrames=captured.physicsFrames+result.stats.sim_frames;
   if(physicalFrames>budget)throw new Error('composition exceeded its allowance');

reproduction.script:
import assert from 'node:assert/strict';
import {readFileSync,mkdirSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {composeArcSections} from '../../scripts/v0/optimizer/arc_composition.ts';
import {normalizeCompilerTimeline} from '../../scripts/v0/optimizer/compiler_input.ts';
import {applyJolt} from '../../scripts/produce/seed.ts';
import {replayGalleryTrack,writeGalleryJson,galleryCompilerIdentity} from '../../scripts/gallery/artifacts.ts';
import {sha} from '../../benchmark/v3/model.ts';
const root='generated/repertoire-20260930/dev-serpentine-strong',out='generated/repertoire-20260930/future-probe';
mkdirSync(out,{recursive:true});
const read=(path:string)=>{const bytes=readFileSync(path);assert.equal(sha(bytes),readFileSync(path+'.sha256','utf8').trim());return JSON.parse(bytes.toString());};
const manifest=read(join(root,'manifest.json')),compiler=galleryCompilerIdentity(process.cwd()),rows:any[]=[];
for(const c of manifest.plan.cases){
 assert.equal(sha(readFileSync(c.source)),c.specSha256);
 const spec=normalizeCompilerTimeline(applyJolt((await import(pathToFileURL(resolve(c.source)).href)).default,manifest.plan.jolt));
 const base=manifest.cells.find((r:any)=>r.caseId===c.id&&r.method==='baseline');
 const record=read(join(root,base.path)),construction=read(join(root,base.id,'construction.json'));
 const reference={...construction,track:record.track,report:read(join(root,base.id,'report.json'))} as any;
 for(const method of ['candidate','mixed']){
  const previous=manifest.cells.find((r:any)=>r.caseId===c.id&&r.method===method),styles=previous.construction.styles;
  const started=performance.now();
  const composed=composeArcSections(spec,331,reference,styles,1000000,{futureEstimate:'simulated'});
  const seconds=(performance.now()-started)/1000;
  const replay=replayGalleryTrack(composed.result.track,c,true);
  assert.deepEqual(replay.trace.frames.slice(0,composed.boundaryFrame+1),record.trace.frames.slice(0,composed.boundaryFrame+1));
  const row={song:c.id,method,style:styles,baselineHash:base.trackHash,previousHash:previous.trackHash,
   previousRms:previous.qualityRms,previousWork:previous.physicalFrames,valid:replay.grade.score.valid,
   rms:replay.grade.score.weightedAxisRms,physicalFrames:composed.physicalFrames,seconds,
   trackHash:sha(JSON.stringify(composed.result.track)),prefixFrames:composed.boundaryFrame+1,
   observations:replay.grade.observations};
  writeGalleryJson(out,c.id+'-'+method+'.json',{...row,track:composed.result.track,report:composed.result.report,construction:composed.result.rows});
  rows.push(row);console.log(JSON.stringify({...row,observations:undefined,style:undefined}));
 }
}
writeGalleryJson(out,'summary.json',{compiler,scriptSha256:sha(readFileSync(import.meta.filename)),source:root,rows});
